 "content": "def transform(grid):
    out = [row[:] for row in grid]
    pts = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 2]
    # The marker row with the widest horizontal span is the spine.
    from collections import Counter
    rows = Counter(r for r,c in pts)
    spine = max(rows, key=lambda r: (rows[r] >= 2, max(c for rr,c in pts if rr == r)-min(c for rr,c in pts if rr == r) if rows[r] >= 2 else 0))
    cols = [c for r,c in pts if r == spine]
    lo, hi = min(cols), max(cols)
    for c in range(lo, hi+1):
        if out[spine][c] == 0: out[spine][c] = 3
    for r,c in pts:
        if r != spine and lo <= c <= hi:
            for rr in range(min(r,spine)+1, max(r,spine)):
                if out[rr][c] == 0: out[rr][c] = 3
    return out

